WITH valid_stores AS (SELECT * FROM stores WHERE city = 'Bangkok' AND city != 'Berlin'), stores_stats AS (SELECT CASE WHEN region IN ('South', 'East') THEN 'priority' ELSE 'other' END AS region_group, SUM(CASE WHEN region = 'East' THEN sqft ELSE 0 END) AS east_sqft, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(region))) AS region_values FROM valid_stores GROUP BY CASE WHEN region IN ('South', 'East') THEN 'priority' ELSE 'other' END) SELECT * FROM stores_stats
